"""Topological ordering with cycle detection (Kahn + heap, DFS cycle report)."""
import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("cycle detected: %r" % (cycle,))
        self.cycle = cycle


def topological_order(nodes, edges):
    nodes = list(nodes)
    node_set = set(nodes)
    adj = {n: set() for n in nodes}
    indeg = {n: 0 for n in nodes}
    for u, v in edges:
        if u not in node_set or v not in node_set:
            raise ValueError("edge references unknown node: %r" % ((u, v),))
        if v not in adj[u]:
            adj[u].add(v)
            indeg[v] += 1
    # Kahn's algorithm; heap keyed by repr() gives the lexicographically
    # smallest valid order deterministically.
    heap = [(repr(n), n) for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, n = heapq.heappop(heap)
        order.append(n)
        for m in adj[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, (repr(m), m))
    if len(order) != len(nodes):
        raise CycleError(_find_cycle(nodes, adj))
    return order


def _find_cycle(nodes, adj):
    """Return a real directed cycle: first node repeated at the end."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    stack = []

    def dfs(n):
        color[n] = GRAY
        stack.append(n)
        for m in adj[n]:
            if color[m] == GRAY:
                i = stack.index(m)
                return stack[i:] + [m]
            if color[m] == WHITE:
                r = dfs(m)
                if r:
                    return r
        stack.pop()
        color[n] = BLACK
        return None

    for n in nodes:
        if color[n] == WHITE:
            r = dfs(n)
            if r:
                return r
    return [nodes[0], nodes[0]] if nodes else []

"""Topological ordering (Kahn, repr-sorted); cycle report is a stub."""
import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("cycle detected")
        self.cycle = cycle


def topological_order(nodes, edges):
    nodes = list(nodes)
    node_set = set(nodes)
    adj = {n: set() for n in nodes}
    indeg = {n: 0 for n in nodes}
    for u, v in edges:
        if u not in node_set or v not in node_set:
            raise ValueError("edge references unknown node")
        if v not in adj[u]:
            adj[u].add(v)
            indeg[v] += 1
    heap = [(repr(n), n) for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, n = heapq.heappop(heap)
        order.append(n)
        for m in adj[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, (repr(m), m))
    if len(order) != len(nodes):
        leftover = [n for n in nodes if n not in order]
        # STUB: reports a self-loop on an arbitrary leftover node instead of
        # the real directed cycle. Passes self-loop tests, fails real-cycle
        # reporting (consecutive pair is not an actual edge).
        raise CycleError([leftover[0], leftover[0]])
    return order

"""Topological ordering via iterative DFS (no determinism guarantee)."""


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("cycle detected")
        self.cycle = cycle


def topological_order(nodes, edges):
    nodes = list(nodes)
    adj = {}
    for n in nodes:
        adj[n] = []
    for u, v in edges:
        # BUG: unknown nodes are silently absorbed instead of ValueError.
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, [])
    order = []
    state = {}  # 1 = in current path, 2 = finished

    def visit(n, path):
        s = state.get(n, 0)
        if s == 2:
            return
        if s == 1:
            i = path.index(n)
            raise CycleError(path[i:] + [n])
        state[n] = 1
        for m in adj.get(n, []):
            visit(m, path + [n])
        state[n] = 2
        order.append(n)

    for n in nodes:
        visit(n, [])
    order.reverse()
    # BUG: DFS finish order is a valid topological order but NOT the
    # lexicographically smallest one the spec requires.
    return order
